/**
 * Sidebar controls for block attributes that carry a custom "control" marker
 * in block.json:
 *
 *   { "type": "integer", "control": "media" }
 *       → Media Library picker (attachment ID, 0 = none) in a "Media" panel.
 *   { "type": "integer", "control": "term", "taxonomy": "…", "parentOnly": true }
 *       → term select (term ID, 0 = none) in a "Category" panel, fed by the
 *         term lists BlocksCore inlines (no REST dependency, no async state).
 *
 * PHP-only (supports.autoRegister) blocks get their other fields generated by
 * core, which has neither control; JS blocks reuse the same panels. Every block
 * without such attributes is passed through untouched. No build step: wp.*
 * globals only, served from source by Blocks\Core\BlocksCore::enqueueEditorAssets(),
 * which also injects the UI strings and term lists as window.starwishxBlockEditor.
 *
 * File: inc/blocks/Assets/editor-media-attributes.js
 */
(function (wp) {
  "use strict";

  var config = window.starwishxBlockEditor || {};
  var MEDIA = config.mediaControl || "media";
  var TERM = config.termControl || "term";
  var i18n = config.i18n || {};
  var termLists = config.terms || {};

  var addFilter = wp.hooks.addFilter;
  var createHigherOrderComponent = wp.compose.createHigherOrderComponent;
  var el = wp.element.createElement;
  var Fragment = wp.element.Fragment;
  var getBlockType = wp.blocks.getBlockType;
  var InspectorControls = wp.blockEditor.InspectorControls;
  // Filled in by wp-editor through the editor.MediaUpload filter; withFilters
  // re-renders once the filter lands, so no dependency on wp-editor is needed.
  var MediaUpload = wp.blockEditor.MediaUpload;
  var MediaUploadCheck = wp.blockEditor.MediaUploadCheck;
  var PanelBody = wp.components.PanelBody;
  var BaseControl = wp.components.BaseControl;
  var Button = wp.components.Button;
  var Flex = wp.components.Flex;
  var FlexItem = wp.components.FlexItem;
  var SelectControl = wp.components.SelectControl;
  var useSelect = wp.data.useSelect;

  /** Mirrors BlocksCore::termOptionsKey(). */
  function termListKey(def) {
    return (def.taxonomy || "") + "|" + (def.parentOnly ? "parents" : "all");
  }

  /** { media: [[name, def], …], term: [[name, def], …] } for one block type. */
  function getControlledAttributes(blockName) {
    var blockType = getBlockType(blockName);
    var attributes = (blockType && blockType.attributes) || {};
    var result = { media: [], term: [] };

    Object.keys(attributes).forEach(function (name) {
      var def = attributes[name];
      if (!def) return;
      if (def.control === MEDIA) result.media.push([name, def]);
      if (def.control === TERM) result.term.push([name, def]);
    });

    return result;
  }

  function MediaAttributeControl(props) {
    var attrName = props.attrName;
    var id = Number(props.value) || 0;
    var setAttributes = props.setAttributes;
    var label = props.def.label || attrName;

    var media = useSelect(
      function (select) {
        return id ? select("core").getMedia(id) : null;
      },
      [id],
    );
    var sizes = (media && media.media_details && media.media_details.sizes) || {};
    var thumb =
      (sizes.medium && sizes.medium.source_url) ||
      (sizes.thumbnail && sizes.thumbnail.source_url) ||
      (media && media.source_url);

    function update(value) {
      var next = {};
      next[attrName] = value;
      setAttributes(next);
    }

    return el(
      BaseControl,
      { __nextHasNoMarginBottom: true },
      el(BaseControl.VisualLabel, null, label),
      el(
        MediaUploadCheck,
        { fallback: el("p", null, i18n.noPermission || "") },
        el(MediaUpload, {
          title: label,
          allowedTypes: ["image"],
          value: id,
          onSelect: function (item) {
            update(Number(item && item.id) || 0);
          },
          render: function (renderProps) {
            return el(
              Fragment,
              null,
              id && thumb
                ? el("img", {
                    src: thumb,
                    alt: (media && media.alt_text) || "",
                    style: {
                      display: "block",
                      maxWidth: "100%",
                      height: "auto",
                      marginBottom: "8px",
                      borderRadius: "2px",
                    },
                  })
                : null,
              el(
                Flex,
                { justify: "flex-start", gap: 2 },
                el(
                  FlexItem,
                  null,
                  el(
                    Button,
                    { variant: "secondary", size: "compact", onClick: renderProps.open },
                    id ? i18n.replace : i18n.select,
                  ),
                ),
                id
                  ? el(
                      FlexItem,
                      null,
                      el(
                        Button,
                        {
                          variant: "tertiary",
                          size: "compact",
                          isDestructive: true,
                          onClick: function () {
                            update(0);
                          },
                        },
                        i18n.remove,
                      ),
                    )
                  : null,
              ),
            );
          },
        }),
      ),
    );
  }

  function TermAttributeControl(props) {
    var attrName = props.attrName;
    var def = props.def;
    var setAttributes = props.setAttributes;
    var terms = termLists[termListKey(def)] || [];

    if (!terms.length) {
      return el("p", null, i18n.noTerms || "");
    }

    var options = [{ label: i18n.selectTerm || "—", value: 0 }].concat(
      terms.map(function (term) {
        return { label: term.name, value: term.id };
      }),
    );

    return el(SelectControl, {
      __nextHasNoMarginBottom: true,
      __next40pxDefaultSize: true,
      label: def.label || attrName,
      value: Number(props.value) || 0,
      options: options,
      onChange: function (value) {
        var next = {};
        next[attrName] = Number(value) || 0;
        setAttributes(next);
      },
    });
  }

  var withCustomControls = createHigherOrderComponent(function (BlockEdit) {
    return function CustomControlsBlockEdit(props) {
      var controlled = getControlledAttributes(props.name);

      if (!controlled.media.length && !controlled.term.length) {
        return el(BlockEdit, props); // core, ACF and every other block: untouched
      }

      // Only the selected block mounts the controls (and their getMedia fetches).
      return el(
        Fragment,
        null,
        el(BlockEdit, props),
        props.isSelected &&
          el(
            InspectorControls,
            null,
            controlled.term.length
              ? el(
                  PanelBody,
                  { title: i18n.termsPanelTitle || "Category", initialOpen: true },
                  controlled.term.map(function (entry) {
                    return el(TermAttributeControl, {
                      key: entry[0],
                      attrName: entry[0],
                      def: entry[1],
                      value: props.attributes[entry[0]],
                      setAttributes: props.setAttributes,
                    });
                  }),
                )
              : null,
            controlled.media.length
              ? el(
                  PanelBody,
                  { title: i18n.panelTitle || "Media", initialOpen: true },
                  controlled.media.map(function (entry) {
                    return el(MediaAttributeControl, {
                      key: entry[0],
                      attrName: entry[0],
                      def: entry[1],
                      value: props.attributes[entry[0]],
                      setAttributes: props.setAttributes,
                    });
                  }),
                )
              : null,
          ),
      );
    };
  }, "withCustomControls");

  addFilter("editor.BlockEdit", "starwishx/custom-controls", withCustomControls);
})(window.wp);
